mapper.select:
SELECT a.FINPROD_ID AS finprodId, /**金融产品代码**/ a.FINPROD_TYPE AS finprodType, /**金融产品类型**/ a.FINPROD_TYPE2 AS finprodType2, /**金融产品类型**/ a.FINPROD_ABBR AS finprodAbbr, /**金融产品简称**/ a.FINPROD_NAME AS finprodName, /**金融产品全称**/ a.PROFIT_TYPE AS profitType, /**收益类型**/ a.COUPON_SPECIES AS couponSpecies, /**息票品种**/ a.CHL_FINPROD_ID AS chlFinprodId, /**通道代码**/ a.FINPROD_MARKET_ID AS finprodMarketId, /**市场代码**/ a.ISSUE_PRICE AS issuePrice, /**发行价**/ a.ISSUE_AMT AS issueAmt, /**发行规模**/ a.CCY AS ccy, /**币种**/ a.BLN_AREA AS blnArea, /**境内外**/ a.CALENDAR_ID AS calendarId, /**交易日历**/ a.TRADE_MARKET AS tradeMarket, /**交易场所**/ a.ISSUE_TYPE AS issueType, /**发行方式**/ a.ISSUER AS issuer, /**发行人**/ a.IDATE AS idate, /**发行日**/ a.VDATE AS vdate, /**起息日**/ a.MDATE AS mdate, /**到期日**/ a.ACTMDATE AS actmdate, /**实际到期日**/ a.IS_CHL AS isChl, /**是否通道**/ a.IS_SUS AS isSus, /**是否永续**/ a.IS_RIGHT AS isRight, /**是否含权**/ a.EXE_DATE exeDate, /**含权债摊销日**/ a.P_FINPROD_ID AS pFinprodId, /**母金融产品代码**/ a.O_FINPROD_ID AS oFinprodId, /**原金融产品代码**/ ofpd.finprod_type AS oFinprodType, /**原金融产品类型**/
b.SALE_LAYER AS saleLayer, /**销售分层**/ b.SALE_PERIOD AS salePeriod, /**销售期次**/ a.OPERATION_TYPE AS openType, /**开放类型**/
/* b.CARRYOVER_FREQ AS carryoverFreq,*/ /**基金结转频率**/ /* d.PAY_CYCLE AS carryoverFreq,*/ /**一体化项目，基金结转频率取现金流支付规则表的支付频率**/ null AS carryoverFreq,/**针对一体化表结构变更：【基金结转频率删除：已转移到现金流支付规则表】。由于标的关联支付规则会出现多条，导致共通方法【查询标的信息】报错，暂时【结转频率】先取空，后期确认解决。**/
b.PUR_SPEED AS purSpeed, /**申购确认速度**/ b.RED_SPEED AS redSpeed, /**赎回确认速度**/ b.IS_COMPOUND_INT AS isCompoundInt, /**add by yanya on 20191012 start 增加面值查询字段 start**/ b.face_value AS faceValue,/**面值**/ /**add by yanya on 20191012 start 增加面值查询字段 end**/ c.TYPE_1 AS type1, /**分类1**/ c.TYPE_2 AS type2, /**分类2**/ c.TYPE_3 AS type3, /**分类3**/ c.TYPE_4 AS type4, /**分类4**/ c.TYPE_5 AS type5, /**分类5**/ c.TYPE_6 AS type6, /**分类6**/ a.REGIST_ORG registOrg /**登记托管机构**/ FROM FIN_PRODUCT a left join FIN_PRODUCT ofpd on ofpd.finprod_id = a.finprod_id LEFT JOIN FIN_PRODUCT_ADD b ON a.finprod_id = b.finprod_id LEFT JOIN FIN_PRODUCT_TYPE c ON a.finprod_id = c.finprod_id
/**LEFT JOIN FIN_CASH_PAY_RULE d ON d.FINPROD_ID = a.FINPROD_ID AND d.FINPROD_TYPE = a.FINPROD_TYPE**/
WHERE 1=1
AND (a.FINPROD_ID IN
null) OR a.FINPROD_ID IN (
#{item}
)
and a.finprod_Type=#{finprodType}
union all SELECT a.FINPROD_ID AS finprodId, /**金融产品代码**/ a.FINPROD_TYPE AS finprodType, /**金融产品类型**/ null as finprodType2, null AS finprodAbbr, /**金融产品简称**/ null as finprodName, /**金融产品全称**/ a.PROFIT_TYPE AS profitType, /**收益类型**/ null AS couponSpecies, /**息票品种**/ a.chl_agrt_id AS chlFinprodId, /**通道代码**/ null AS finprodMarketId, /**市场代码**/ null AS issuePrice, /**发行价**/ null AS issueAmt, /**发行规模**/ a.CCY AS ccy, /**币种**/ null AS blnArea, /**境内外**/ a.CALENDAR_ID AS calendarId, /**交易日历**/ a.TRADE_MARKET AS tradeMarket, /**交易场所**/ null AS issueType, /**发行方式**/ null AS issuer, /**发行人**/ null AS idate, /**发行日**/ a.VDATE AS vdate, /**起息日**/ a.MDATE AS mdate, /**到期日**/ a.mdate AS actmdate, /**实际到期日**/ null AS isChl, /**是否通道**/ null AS isSus, /**是否永续**/ null AS isRight, /**是否含权**/ null as exeDate, /**含权债摊销日**/ null AS pFinprodId, /**母金融产品代码**/ null AS oFinprodId, /**原金融产品代码**/ null AS oFinprodType, /**原金融产品类型**/
null AS saleLayer, /**销售分层**/ null AS salePeriod, /**销售期次**/ null AS openType, /**开放类型**/ null AS carryoverFreq, /**基金结转频率**/ null AS purSpeed, /**申购确认速度**/ null AS redSpeed, /**赎回确认速度**/ null AS isCompoundInt, /**add by yanya on 20191012 start 增加面值查询字段 start**/ null AS faceValue,/**面值**/ /**add by yanya on 20191012 start 增加面值查询字段 end**/ c.TYPE_1 AS type1, /**分类1**/ c.TYPE_2 AS type2, /**分类2**/ c.TYPE_3 AS type3, /**分类3**/ null AS type4, /**分类4**/ null AS type5, /**分类5**/ null AS type6, /**分类6**/ null registOrg /**登记托管机构**/ FROM FIN_trade_PRODUCT a LEFT JOIN FIN_PRODUCT_ADD b ON a.finprod_id = b.finprod_id LEFT JOIN FIN_PRODUCT_TYPE c ON a.finprod_id = c.finprod_id WHERE 1=1
AND (a.FINPROD_ID IN
null) OR a.FINPROD_ID IN (
#{item}
)
and a.finprod_Type=#{finprodType}
and a.branch= #{branch}

SELECT CASH_ID, EXERCISE_TYPE, VDATE, MDATE, EXERCISE_DATE, EXERCISE_STATUS, EXERCISE_PRICE, EXERCISE_REMARK, FINPROD_ID, FINPROD_TYPE, BRANCH, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME FROM FIN_EXERCISE_PLAN WHERE 1 = 1
AND (FINPROD_ID IN
null) OR FINPROD_ID IN (
#{item}
)
AND FINPROD_TYPE=#{finprodType}
AND EXERCISE_DATE > #{exerciseDate}
AND EXERCISE_TYPE=#{exerciseType}
ORDER BY FINPROD_ID,EXERCISE_DATE ASC

SELECT DISTINCT TEMP.finprodId as finprodId, TEMP.isCashManage as isCashManage FROM (select b.BOOKSET_ID as finprodId, a.is_cash_manage as isCashManage from fin_product_add a inner join BOK_BOOKSET b on b.ACCT_SUBJECT_TYPE = 'F16' and b.BOOKSET_ID = a.FINPROD_ID where b.BOOKSET_ID in
null) OR b.BOOKSET_ID IN (
#{item}
UNION ALL select d.BOOKSET_ID as finprodId, a.is_cash_manage as isCashManage from fin_product_add a inner join ptl_portfolio b on a.PORTFOLIO_ID = b.PORTFOLIO_ID inner join ptl_portfolio c on c.PARENT_PORTFOLIO_ID = b.PORTFOLIO_ID inner join BOK_BOOKSET d on d.ACCT_SUBJECT_TYPE = 'F18' and d.BOOKSET_ID = c.PORTFOLIO_ID where d.BOOKSET_ID in
null) OR d.BOOKSET_ID IN (
#{item}
UNION ALL select c.BOOKSET_ID_SON as finprodId, a.is_cash_manage as isCashManage from fin_product_add a inner join BOK_BOOKSET b on b.ACCT_SUBJECT_TYPE = 'F16' and b.BOOKSET_ID = a.FINPROD_ID inner join BOK_BOOKSET_RE c on c.BOOKSET_ID = b.BOOKSET_ID where c.BOOKSET_ID_SON in
null) OR c.BOOKSET_ID_SON IN (
#{item}
UNION ALL select e.BOOKSET_ID_SON as finprodId, a.is_cash_manage as isCashManage from fin_product_add a inner join ptl_portfolio b on a.PORTFOLIO_ID = b.PORTFOLIO_ID inner join ptl_portfolio c on c.PARENT_PORTFOLIO_ID = b.PORTFOLIO_ID inner join BOK_BOOKSET d on d.ACCT_SUBJECT_TYPE = 'F18' and d.BOOKSET_ID = c.PORTFOLIO_ID inner join BOK_BOOKSET_RE e on e.BOOKSET_ID = d.BOOKSET_ID where e.BOOKSET_ID_SON in
null) OR e.BOOKSET_ID_SON IN (
#{item}
) TEMP ORDER BY TEMP.finprodId

select BOOKSET_ID, BUSI_ID, CDATE, RECAL_TYPE, DAILYDSC_YIELD from BOK_AMO_CONFIG where 1=1
AND (BUSI_ID IN
null) OR BUSI_ID IN (
#{item}
)
AND CDATE = #{cdate} AND (
(BOOKSET_ID IN
null) OR BOOKSET_ID IN (
#{item}
)
OR BOOKSET_ID = 'ALL') ORDER BY (DECODE(BOOKSET_ID ,'ALL',2,1))

    	        SELECT
					ECL_VAULE
				FROM
					TRD_ASSET_LOSS
				WHERE
					VAL_DATE  <=  #{HAPPEN_DATE}
					AND STATUS = #{TRADE_STATUS_01}
					AND STAGE =  #{stageP3}
					AND SEC_ID = #{secId}
				ORDER by VAL_DATE DESC

select a.vdate,/*起息日*/ a.mdate,/*到期日*/ a.trade_date tradeDate, a.settle_date settleDate, a.is_clean isClean,/*是否结清*/ a.finprod_id finprodId,/*金融产品代码*/ a.finprod_type finprodType,/*金融产品类型*/ a.trade_amt tradeAmt, /*交易金额*/ b.bookset_id booksetId from trd_product_deal a inner join bok_deal_accounting b on a.trade_id = b.busi_no where 1 = 1 and a.ps = 'T22'
AND (b.bookset_id IN
null) OR b.bookset_id IN (
#{item}
)
and a.mdate = #{calDate,jdbcType=DATE}
AND (a.finprod_id IN
null) OR a.finprod_id IN (
#{item}
)
